entries.example:
// a webhook: HMAC-SHA256 of the body, compared in hex
Check = New DataHashing(HashFunction.SHA256, Secret);
Check.Append(Body);
if (Lower(GetHexStringFromBinaryData(Check.HashSum)) <> Signature) { Raise("the signature does not match"); }

